      "ruleSummary": "This unit teaches three related uses of the definite article the. (1) the + noun to talk about a type of thing (an animal, a machine, an invented device) rather than one specific example: 'The giraffe is the tallest of all animals' (a specific type of animal, not a specific giraffe), 'The bicycle is an excellent means of transport', 'When was the camera invented?', 'The dollar is the currency of the United States'. The same pattern is used for musical instruments: 'Can you play the guitar?', 'The piano is my favourite instrument'. Compare a and the: 'I'd like to have a piano. but I can't play the piano.'; 'We saw a giraffe at the zoo. but The giraffe is my favourite animal.'. Note that man (without the) means human beings in general, the human race: 'What do you know about the origins of man?' (not the man). (2) the + adjective (with no noun) to talk about a group of people: the old, the rich, the homeless, the sick, the elderly, the poor, the unemployed, the injured. 'Do you think the rich should pay higher taxes?', 'We need to do more to help the homeless.'. These phrases are plural and take a plural verb; for one person we say a rich man (not a rich), a homeless person (not a homeless). We also say the old (not the olds), the poor (not the poors). (3) the + a nationality adjective to talk about the people of a country. Nationality words ending in -ch or -sh (the French, the Dutch, the British, the English, the Spanish) and words ending in -ese or -ss (the Chinese, the Portuguese, the Swiss) take the and are plural in meaning: 'The French are famous for their food' (not French are ...). We don't say a French or an English (singular); we say a French woman, an English guy. Words ending in -ese or -ss can also be singular: a Chinese, a Swiss. With other nationality words the plural simply adds -s, usually without the: an Italian/Italians, a Mexican/Mexicans, a Thai/Thais ('Italians are very friendly'). In every case you can also say adjective + people: French people, Chinese people, Mexican people. A correct student sentence should use the with a general type of thing/instrument, the + adjective for a group of people, or the + nationality word, matching one of these patterns."
