      "instructionsEn": "Write 2-3 English sentences using noun + noun compounds: for example a compound naming a job or everyday object (a bus driver, a frying pan, a shopping bag), or a number + singular noun acting as an adjective before another noun (a two-hour meeting, a five-day trip, a ten-year-old car).",
      "ruleSummary": "This unit teaches noun + noun compounds, where the first noun acts like an adjective describing what kind of thing/person/idea the second noun is: a bus driver (= the driver of a bus), income tax, the city centre, an apple tree, a Paris hotel, my life story, a television camera/programme/studio/producer, language/marriage/health/work problems. The first word can end in -ing: a frying pan, a washing machine, a swimming pool. More than two nouns can be strung together: a hotel reception desk, the World Swimming Championships, a table tennis table. Sometimes the compound is written as one word and sometimes as two, with no fixed rule (a headache, toothpaste, a weekend vs. a car park, a road sign); when unsure, write two words. Compare a coffee cup (maybe empty, a cup for coffee) with a cup of coffee (a cup that has coffee in it), and a shopping bag with a bag of shopping. Crucially, when a number + noun modifies another noun, the first noun stays singular even though the meaning is plural: a three-hour journey (not a three hours journey), a ten-pound note, a four-week course, a six-mile walk, two 14-year-old girls. Compare It was a four-week course (not a four weeks course) with The course lasted four weeks, where weeks is plural because it is not modifying a following noun. A correct student sentence should either build a natural noun + noun compound (job, object, or place name) or use a number + singular noun correctly as a modifier directly before another noun."
