      "ruleSummary": "This unit teaches when to use -'s (apostrophe + s) versus of ... to show possession or belonging. -'s is used mostly for people or animals: Tom's computer isn't working (not the computer of Tom), Chris's children, the cat's tail, and it can be used without a noun after it: It's my sister's (= my sister's book). -'s is not used after a long group of words: my friend's mother, but the mother of the man we met yesterday (not the man we met yesterday's mother). Note fixed patterns like a woman's hat (= a hat for a woman), a boy's name (= a name for a boy), a bird's egg (= an egg laid by a bird). With a singular noun use -'s: my sister's room, Mr Carter's house. With a plural noun ending in -s, put the apostrophe after the s: my sisters' room, the Carters' house. If a plural noun does not end in -s (men/women/children/people), use -'s: the men's changing room, a children's book. You can use -'s after more than one noun: Jack and Karen's children, Mr and Mrs Carter's house. For things and ideas, normally use of: the temperature of the water (not the water's temperature), the name of the book, the owner of the restaurant; fixed phrases like the beginning/end/middle of..., the top/bottom of..., the front/back/side of... also always use of: the beginning of the month, the top of the hill, the back of the car. For an organisation (a group of people) you can usually use either -'s or of: the government's decision or the decision of the government. -'s is also used for places: the city's streets, the world's population, Italy's prime minister. -'s is used with time words: yesterday's newspaper, next week's meeting, and in the same way today's/tomorrow's/this evening's/Monday's. -'s (or -s' with a plural word) is also used with periods of time: a week's holiday, three weeks' holiday, ten minutes' walk, an hour's sleep. A correct student sentence should either use -'s correctly for a person, animal, organisation, place, or time word, or use of correctly for a thing, an idea, or one of the fixed of phrases (the top/back/beginning of...)."
