      "instructionsEn": "Write 2-3 English sentences: use a reflexive pronoun (myself/yourself/himself/herself/itself/ourselves/yourselves/themselves) correctly, or use each other/one another for a mutual action between two or more people.",
      "ruleSummary": "This unit teaches reflexive pronouns (myself, yourself, himself, herself, itself, ourselves, yourselves, themselves) and how they differ from each other/one another. Reflexive pronouns are used when the subject and object of a verb are the same: Steve introduced himself to the other guests. Forms: myself, yourself (one person), himself/herself/itself, yourselves (more than one person), ourselves, themselves. Examples: I'll pay for myself (not I'll pay for me), she really enjoyed herself, do you talk to yourself sometimes, help yourselves. Reflexive pronouns are NOT used after feel/relax/concentrate/meet: I feel nervous, I can't relax, you need to concentrate (not concentrate yourself), what time shall we meet tomorrow. They are also not normally used after wash/shave/dress: he got up, washed, shaved and dressed (not washed himself); you can also say get dressed. Compare -selves and each other: Kate and Joe looked at themselves (together they looked at themselves, e.g. in a mirror) versus Kate and Joe looked at each other (Kate looked at Joe and Joe looked at Kate, a mutual action) - one another can be used instead of each other: how long have you known each other/one another, they don't like each other/one another, do they live near each other/one another. Reflexive pronouns are also used for emphasis, meaning 'that person/thing and nobody/nothing else': I repaired it myself (= not another person), you can do it yourself, let's paint the house ourselves, the film itself wasn't very good but I loved the music, Lisa doesn't think so herself / Lisa herself doesn't think so. A correct student sentence should either use a reflexive pronoun correctly (matching subject and object, or for emphasis) or use each other/one another correctly for a mutual action, and should avoid a reflexive pronoun after feel/relax/concentrate/meet/wash/shave/dress."
