      "instructionsEn": "Write 2-3 English sentences: use the structure a friend of mine/yours etc., my own + noun, or on my own/by myself correctly.",
      "ruleSummary": "This unit teaches three related structures with mine/yours/own/myself. (1) a friend of mine/yours/his/hers/ours/theirs = one of my/your/his/her/our/their friends: I'm going to a wedding on Saturday. A friend of mine is getting married (not a friend of me). We went on holiday with some friends of ours (not some friends of us). Harry had an argument with a neighbour of his. In the same way, with a person's name: a friend of my sister's, a friend of Tom's (= one of my sister's/Tom's friends). (2) my own / your own / her own etc. + noun (not an own house, an own car) = something that is only mine/yours, not shared or borrowed: I want my own room. Vicky and Gary would like to have their own house. It's my own fault that I have no money. Why don't you use your own (car)? You can also say a room of my own, problems of his own. Own + noun is also used to say you do something yourself instead of somebody else doing it for you: Paul usually cuts his own hair (= he cuts it himself). I'd like to grow my own vegetables (= grow them myself instead of buying them). (3) on my own and by myself both mean 'alone': I like living on my own / by myself. Some people prefer to live on their own / by themselves. Jack was sitting on his own / by himself in a corner. Did you go on holiday on your own / by yourself? A correct student sentence should use of mine/yours etc. correctly (not 'of me'/'of us'), or my own/your own etc. correctly (not 'an own X'), or on my own/by myself correctly (not 'by my own' or 'on myself')."
